<div id="copy-toast" class="copy-toast" role="status" aria-live="polite"></div>
<style>.copy-toast{position:fixed;bottom:24px;left:50%;transform:translate(-50%,16px);background:#182238;color:#fff;padding:10px 16px;border-radius:9px;opacity:0;pointer-events:none;transition:.2s;z-index:2000}.copy-toast.show{opacity:1;transform:translate(-50%,0)}</style>
<script>
const endpoint=@json(route('elasticsearch-monitoring.snapshots.data',['locale'=>$locale]));
const labels=@json($texts);
const copyLabels={"tr":{"copy":"Kopyala","all":"Tüm mapping'i kopyala","field":"Alanı kopyala","done":"Panoya kopyalandı","fail":"Kopyalama başarısız"},"en":{"copy":"Copy","all":"Copy entire mapping","field":"Copy field","done":"Copied to clipboard","fail":"Copy failed"},"es":{"copy":"Copiar","all":"Copiar todo el mapping","field":"Copiar campo","done":"Copiado al portapapeles","fail":"Error al copiar"},"zh_CN":{"copy":"复制","all":"复制完整 mapping","field":"复制字段","done":"已复制到剪贴板","fail":"复制失败"},"hi":{"copy":"कॉपी करें","all":"पूरा mapping कॉपी करें","field":"फ़ील्ड कॉपी करें","done":"क्लिपबोर्ड पर कॉपी किया गया","fail":"कॉपी विफल"},"ar":{"copy":"نسخ","all":"نسخ mapping بالكامل","field":"نسخ الحقل","done":"تم النسخ إلى الحافظة","fail":"فشل النسخ"}}[@json($locale)] || {"copy":"Copy","all":"Copy entire mapping","field":"Copy field","done":"Copied to clipboard","fail":"Copy failed"};
function showCopyToast(message){const el=document.getElementById('copy-toast');if(!el)return;el.textContent=message;el.classList.add('show');clearTimeout(window.__copyToastTimer);window.__copyToastTimer=setTimeout(()=>el.classList.remove('show'),1800);}
async function copyText(value){try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(String(value));else{const el=document.createElement('textarea');el.value=String(value);el.style.position='fixed';el.style.opacity='0';document.body.append(el);el.select();const ok=document.execCommand('copy');el.remove();if(!ok)throw new Error('Clipboard unavailable');}showCopyToast(copyLabels.done);}catch(e){showCopyToast(copyLabels.fail);}}
document.addEventListener('click',event=>{const button=event.target.closest('[data-copy-value]');if(button){event.preventDefault();copyText(button.dataset.copyValue);}});

const fmt=value=>Number(value||0).toLocaleString(document.documentElement.lang);
const esc=value=>String(value??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const states={SUCCESS:labels.successful,PARTIAL:labels.partial,FAILED:labels.failed,IN_PROGRESS:labels.running,INCOMPATIBLE:'INCOMPATIBLE'};
function date(value){if(!value)return '—';const parsed=new Date(value);return Number.isNaN(parsed.getTime())?'—':parsed.toLocaleString(document.documentElement.lang)}
function duration(ms){if(ms===null||ms===undefined||ms<0)return '—';const seconds=Math.floor(ms/1000);if(seconds<60)return seconds+' '+labels.seconds;const minutes=Math.floor(seconds/60);if(minutes<60)return minutes+' '+labels.minutes;const hours=Math.floor(minutes/60);if(hours<24)return hours+' '+labels.hours;return Math.floor(hours/24)+' '+labels.days}
function badge(state){const key=String(state||'UNKNOWN').toLowerCase().replace('_','-');return '<span class="status status-'+esc(key)+'">'+esc(states[state]||state)+'</span>'}
function render(payload){
 const summary=payload.summary||{},repos=payload.repositories||[],snapshots=payload.snapshots||[];
 document.getElementById('repo-count').textContent=fmt(summary.repositories);
 document.getElementById('snapshot-count').textContent=fmt(snapshots.length);
 document.getElementById('snapshot-total').textContent=labels.showing+' '+fmt(snapshots.length)+' / '+labels.total+' '+fmt(summary.snapshots);
 document.getElementById('successful-count').textContent=fmt(summary.successful);
 document.getElementById('partial-count').textContent=fmt(summary.partial);
 document.getElementById('failed-count').textContent=fmt(summary.failed);
 document.getElementById('running-count').textContent=fmt(summary.in_progress)+' '+labels.running;
 const latest=payload.meta?.latest_successful;
 document.getElementById('latest-success').textContent=latest?latest.name:labels.never;
 document.getElementById('latest-success-meta').textContent=latest?latest.repository+' · '+date(latest.start_time)+' · '+duration(latest.duration_in_millis):'';
 document.getElementById('repository-list').innerHTML=repos.length?repos.map(repo=>'<div class="col-12 col-md-6 col-xl-4"><div class="panel repo h-100"><div class="d-flex justify-content-between gap-2"><h3>'+esc(repo.name)+' <button type="button" class="btn btn-sm btn-link p-0 text-secondary" data-copy-value="'+esc(repo.name)+'" title="'+copyLabels.copy+'">⧉</button></h3><span class="badge text-bg-light">'+esc(repo.type)+'</span></div><div class="small muted mb-2">'+labels.total+': '+fmt(repo.total_snapshots)+'</div>'+(repo.error?'<div class="small text-danger">'+labels.repo_error+'</div>':(repo.latest_successful?'<div class="small muted">'+labels.latest+':</div><div class="fw-semibold">'+date(repo.latest_successful.start_time)+'</div>':'<div class="small muted">'+labels.never+'</div>'))+'</div></div>').join(''):'<div class="col-12"><div class="panel repo muted">'+labels.no_repositories+'</div></div>';
 document.getElementById('snapshot-table').innerHTML=snapshots.length?snapshots.map(s=>'<tr><td>'+esc(s.repository)+' <button type="button" class="btn btn-sm btn-link p-0 text-secondary" data-copy-value="'+esc(s.repository)+'" title="'+copyLabels.copy+'">⧉</button></td><td><span class="fw-semibold">'+esc(s.name)+'</span> <button type="button" class="btn btn-sm btn-link p-0 text-secondary" data-copy-value="'+esc(s.name)+'" title="'+copyLabels.copy+'">⧉</button>+(s.failure_reasons?.length?'<div class="small text-danger">'+esc(s.failure_reasons.join('; '))+'</div>':'')+'</td><td>'+badge(s.state)+'</td><td>'+date(s.start_time)+'</td><td>'+duration(s.duration_in_millis)+'</td><td>'+fmt(s.indices_count)+'</td><td>'+fmt(s.data_streams_count)+'</td><td>'+fmt(s.shards_successful)+' / '+fmt(s.shards_total)+(s.shards_failed?' <span class="text-danger">('+fmt(s.shards_failed)+' '+labels.failed_shards+')</span>':'')+'</td><td>'+fmt(s.failure_count)+'</td></tr>').join(''):'<tr><td colspan="9" class="text-center py-4 muted">'+labels.no_snapshots+'</td></tr>';
 document.getElementById('history-count').textContent=fmt(snapshots.length);
 document.getElementById('updated').textContent=labels.updated+': '+new Date().toLocaleTimeString(document.documentElement.lang);
}
async function load(){
 const notice=document.getElementById('notice');
 try{
  const response=await fetch(endpoint,{headers:{Accept:'application/json'}});if(!response.ok)throw new Error('HTTP '+response.status);
  const payload=await response.json();
  if(!payload.available){notice.textContent=labels.permission;notice.classList.remove('d-none');render(payload);return}
  notice.classList.add('d-none');render(payload);
 }catch(error){notice.textContent=labels.error+' '+error.message;notice.classList.remove('d-none')}
}
document.getElementById('refresh').addEventListener('click',load);
load();setInterval(load,60000);
</script>
    @include('elasticsearch-monitoring::partials.theme')
